urlset:

    {{ base_url }}


    {{ base_url }}event/list/


    {{ base_url }}community/list/


    {{ base_url }}about/


    {{ base_url }}event/detail/history/


    {{ base_url }}community/archive/


    {{ base_url }}community/criteria/


    {{ base_url }}privacy/


    {{ base_url }}terms/


    {{ base_url }}news/



    {{ base_url|slice:":-1" }}{% url 'vket:list' %}


    {{ base_url }}guide/
    {% if guide_top_lastmod %}{{ guide_top_lastmod }}{% endif %}

{% for page in guide_pages %}

        {{ base_url }}guide/{{ page.path }}/
        {% if page.lastmod %}{{ page.lastmod }}{% endif %}

{% endfor %}

{% for collaboration in vket_collaborations %}

        {{ base_url|slice:":-1" }}{{ collaboration.get_absolute_url }}
        {{ collaboration.updated_at|date:"Y-m-d" }}

{% endfor %}

{% for post in news_posts %}

        {{ base_url }}news/{{ post.slug }}/
        {{ post.updated_at|date:"Y-m-d" }}

{% endfor %}

{% for event_detail in event_details %}

        {{ base_url }}event/detail/{{ event_detail.pk }}/
        {{ event_detail.updated_at|date:"Y-m-d" }}

{% endfor %}
{% for community in communities %}

        {{ base_url }}community/{{ community.pk }}/
        {{ community.updated_at|date:"Y-m-d" }}

{% endfor %}
